using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace DoomSNESed {
    public sealed class NativeTextPreview:PictureBox {
        protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);if(Image==null)return;double scale=Math.Min(Width/(double)Image.Width,Height/(double)Image.Height);if(scale>=1)scale=Math.Floor(scale);int w=Math.Max(1,(int)(Image.Width*scale)),h=Math.Max(1,(int)(Image.Height*scale));e.Graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;e.Graphics.DrawImage(Image,new Rectangle((Width-w)/2,(Height-h)/2,w,h),new Rectangle(0,0,Image.Width,Image.Height),GraphicsUnit.Pixel);}
    }
    public sealed partial class ConverterForm {
        readonly Dictionary<int,string> textErrors=new Dictionary<int,string>();readonly Dictionary<int,TextReplacement> textDrafts=new Dictionary<int,TextReplacement>();readonly List<Action> textFlushers=new List<Action>();
        void FlushText(){foreach(var flush in textFlushers)flush();Bin.Require(textErrors.Count==0,"Fix invalid Ending Text / Credits / Copyright edits before building: "+string.Join("; ",textErrors.Values.ToArray()));}
        readonly List<TextReplacement> textChanges=new List<TextReplacement>();
        void AddTextTabs(){AddTextTab(false);AddTextTab(true);AddCopyrightTab();}
        void AddTextTab(bool credits){var tab=new TabPage(credits?"Credits":"Ending Text"){BackColor=Theme.Panel};tabs.TabPages.Add(tab);var split=new SplitContainer{Dock=DockStyle.Fill,Width=1160,SplitterDistance=590};tab.Controls.Add(split);
            var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=90,Padding=new Padding(8)};var load=Theme.Button("Load from base ROM");var page=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=145,BackColor=Theme.Raised,ForeColor=Theme.Text};page.Items.AddRange(credits?new object[]{"Credits page 1","Credits page 2"}:new object[]{"Episode 1 ending","Episode 2 ending","Episode 3 ending"});var reset=Theme.Button("Restore original");var wrap=Theme.Button("Wrap to 30 columns");tools.Controls.Add(load);tools.Controls.Add(page);tools.Controls.Add(reset);if(!credits)tools.Controls.Add(wrap);
            var status=new Label{Dock=DockStyle.Bottom,Height=90,Padding=new Padding(8),ForeColor=Theme.Mint};var preview=new NativeTextPreview{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Theme.Background};split.Panel2.Controls.Add(preview);split.Panel2.Controls.Add(new Label{Dock=DockStyle.Top,Height=64,Padding=new Padding(10),Text=credits?"Native font preview over the title background\nChanges refresh as you type.":"Native font + this episode's intermission artwork\nChanges refresh as you type.",ForeColor=Theme.Mint});
            var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,AcceptsReturn=true,ScrollBars=ScrollBars.Both,WordWrap=false,BackColor=Theme.Background,ForeColor=Theme.Text,Font=new Font("Consolas",11),MaxLength=4096};var rows=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Theme.Background,ForeColor=Color.Black};rows.Columns.Add(new DataGridViewTextBoxColumn{Name="Row (0..27)",FillWeight=45});rows.Columns.Add(new DataGridViewTextBoxColumn{Name="Column",FillWeight=40});rows.Columns.Add(new DataGridViewTextBoxColumn{Name="Text",FillWeight=200});split.Panel1.Controls.Add(credits?(Control)rows:text);split.Panel1.Controls.Add(status);split.Panel1.Controls.Add(tools);
            Rom rom=null;bool loading=false;var refreshTimer=new Timer{Interval=120};
            Func<int> id=()=>page.SelectedIndex+1+(credits?3:0);
            Action redraw=delegate{if(rom==null||page.SelectedIndex<0)return;try{var replacement=textChanges.FirstOrDefault(t=>t.Id==id());Image old=preview.Image;preview.Image=TextAssets.Preview(rom,id(),replacement,graphicChanges);if(old!=null)old.Dispose();}catch(Exception ex){status.Text=ex.Message;status.ForeColor=Color.Salmon;}};
            Action stage=delegate{if(loading||rom==null||page.SelectedIndex<0)return;var replacement=new TextReplacement{Id=id(),Text=text.Text};try{if(credits){replacement.Lines=new List<CreditLine>();foreach(DataGridViewRow row in rows.Rows){int y=0,x=0;Bin.Require(int.TryParse(Convert.ToString(row.Cells[0].Value),out y)&&int.TryParse(Convert.ToString(row.Cells[1].Value),out x),"Row and column must be whole numbers.");var line=new CreditLine{Record=(int)row.Tag,Row=y,Column=x,Text=Convert.ToString(row.Cells[2].Value)??""};TextAssets.ValidateCredit(line,page.SelectedIndex+1);replacement.Lines.Add(line);}status.Text="Staged "+replacement.Lines.Count+" native text entries. Row 0..27, column 0..31; text must fit 32 columns. Empty text hides an entry. Overlapping entries draw in native table order.";}else{byte[] bytes=TextAssets.EncodeStory(id(),text.Text,rom.Bytes);status.Text="Staged: "+bytes.Length+" / "+TextAssets.StoryCapacity(rom.Bytes,id())+" native text bytes. Up to 30 columns and 24 rows. Blank lines preserve spacing; top margin is 4 rows.";}textErrors.Remove(id());textDrafts.Remove(id());status.ForeColor=Theme.Mint;textChanges.RemoveAll(t=>t.Id==id());textChanges.Add(replacement);AssetsChanged();redraw();}catch(Exception ex){textDrafts[id()]=replacement;textErrors[id()]=ex.Message;status.ForeColor=Color.Salmon;status.Text="Not staged: "+ex.Message+" Last valid text remains in the build.";if(!credits){Image old=preview.Image;preview.Image=TextAssets.Preview(rom,id(),replacement,graphicChanges);if(old!=null)old.Dispose();}}};
            textFlushers.Add(delegate{if(refreshTimer.Enabled){refreshTimer.Stop();stage();}});refreshTimer.Tick+=delegate{refreshTimer.Stop();stage();};
            Action changed=delegate{if(loading)return;refreshTimer.Stop();refreshTimer.Start();};text.TextChanged+=delegate{changed();};rows.CellValueChanged+=delegate{changed();};rows.CurrentCellDirtyStateChanged+=delegate{if(rows.IsCurrentCellDirty)rows.CommitEdit(DataGridViewDataErrorContexts.Commit);};
            Action populate=delegate{if(rom==null||page.SelectedIndex<0)return;loading=true;try{var replacement=textDrafts.ContainsKey(id())?textDrafts[id()]:textChanges.FirstOrDefault(t=>t.Id==id());if(credits){rows.Rows.Clear();foreach(var line in replacement==null?TextAssets.ReadCredits(rom.Bytes,page.SelectedIndex+1):replacement.Lines){int index=rows.Rows.Add(line.Row,line.Column,line.Text);rows.Rows[index].Tag=line.Record;}}else text.Text=replacement==null?TextAssets.Story(rom.Bytes,id()):replacement.Text;status.ForeColor=Theme.Mint;status.Text=replacement==null?"Original ROM text. Changes stage automatically when valid.":"Replacement staged. Changes stage automatically when valid.";redraw();}finally{loading=false;}};
            Action loadRom=delegate{try{rom=new Rom(romPath.Text,resources);if(page.SelectedIndex<0)page.SelectedIndex=0;populate();}catch(Exception ex){status.Text=ex.Message;}};load.Click+=delegate{loadRom();};page.SelectedIndexChanged+=delegate{refreshTimer.Stop();populate();};reset.Click+=delegate{if(rom==null)return;textChanges.RemoveAll(t=>t.Id==id());textErrors.Remove(id());textDrafts.Remove(id());AssetsChanged();populate();};wrap.Click+=delegate{text.Text=TextAssets.Wrap(text.Text);};tabs.SelectedIndexChanged+=delegate{if(tabs.SelectedTab!=tab)return;if(rom==null&&System.IO.File.Exists(romPath.Text))loadRom();else populate();};
            romPath.TextChanged+=delegate{if(refreshTimer.Enabled){refreshTimer.Stop();stage();}rom=null;var old=preview.Image;preview.Image=null;if(old!=null)old.Dispose();if(tabs.SelectedTab==tab&&System.IO.File.Exists(romPath.Text))loadRom();};
            // Flush pending edits before Analyze/Build or leaving this page.
            tab.Leave+=delegate{if(refreshTimer.Enabled){refreshTimer.Stop();stage();}};FormClosed+=delegate{refreshTimer.Dispose();if(preview.Image!=null)preview.Image.Dispose();};
        }
    }
}


